/** Index into `previews[slug]` of the most representative screenshot, used as the card cover and chapter banner. */
export const coverIndex: Record<string, number> = {
  ikai: 2, // control-centre page, not the thin bar strips
  "javascript-para-subir-de-nivel": 1, // chapter with highlighted code
  "omarchy-zen": 1, // zen-floral
  "tcg-store": 0, // desktop home
  "amplixme-fs-0009": 0,
  "obsidian-backend-template": 1, // dashboard, landscape crop
  "skorify-frontend": 2, // merged PR #63
  "fitness-tracker": 0,
  "linux-win-setup": 0,
  "weather-app": 0,
  "ghibli-explorer": 0,
};

/** Shots that read well inside a card frame (landscape-ish, not a thin strip); the active card cycles through them. */
export const cycleShots = (slug: string): Shot[] => (previews[slug] ?? []).filter((s) => s.height >= 200 && s.width / s.height >= 0.9);

export const coverShot = (slug: string): Shot | undefined => previews[slug]?.[coverIndex[slug] ?? 0];
